<article class="quiz-card"><div class="quiz-card-top"><span class="subject-icon" style="--subject:{{ $quiz->category->color }}">{{ mb_strtoupper(mb_substr($quiz->category->name,0,2)) }}</span><span class="soft-badge">{{ $quiz->category->name }}</span></div><h3>{{ $quiz->title }}</h3><p>{{ Illuminate\Support\Str::limit($quiz->description ?: 'A fresh opportunity to test your understanding.',130) }}</p><div class="quiz-meta"><span><x-icon name="book"/>{{ $quiz->question_count }} questions</span><span><x-icon name="clock"/>{{ $quiz->duration_minutes }} minutes</span></div><div class="quiz-card-bottom"><small>Pass at {{ $quiz->pass_percentage }}% @if(isset($quiz->attempts_count))<br>{{ $quiz->attempts_count }}/{{ $quiz->max_attempts }} attempts used @endif</small><form method="post" action="{{ route('quizzes.start',$quiz) }}" data-ajax data-confirm="Start this quiz? The {{ $quiz->duration_minutes }}-minute timer begins immediately and continues if you close this window.">@csrf<button class="btn btn-primary btn-sm" type="submit">Start quiz <x-icon name="arrow"/></button></form></div></article>
